          "description": "CC recipients, comma-separated.",
          "title": "Cc"
        },
        "bcc": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "BCC recipients, comma-separated.",
          "title": "Bcc"
        },
        "from_": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Sender email address (alias).",
          "title": "From"
        },
        "from_name": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Display name for sender.",
          "title": "From Name"
        },
        "reply_to": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Reply-to email address.",
          "title": "Reply To"
        },
        "body_type": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": "plain",
          "description": "Body format - \"plain\" or \"html\" (default: \"plain\").",
          "title": "Body Type"
        },
        "signature": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Email signature to append.",
          "title": "Signature"
        },
        "label_ids": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
