    "parameters": {
      "properties": {
        "query": {
          "default": "",
          "description": "Gmail search query. Supports operators: from:, to:, subject:,\nlabel:, is:unread, is:read, is:starred, has:attachment, OR, and\nplain text (e.g., \"from:user@example.com is:unread\").",
          "title": "Query",
          "type": "string"
        },
        "id": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
